import os
import json
import uuid
import datetime
import requests
from agents import function_tool
RI_API = os.environ.get('REINSURER_API_URL', 'https://api.reinsurer-partner.com/v2')
RI_KEY = os.environ.get('REINSURER_API_KEY', '')
NOTICE_LOG = os.environ.get('RI_NOTICE_LOG', 'ri_large_loss_notices.jsonl')


def _record_notice_sent(claim_number, treaty_id, amount, currency, ack_ref):
    # Append an audit record of the acknowledged notice to the local notice log
    entry = {'claim_number': claim_number, 'treaty_id': treaty_id, 'gross_amount': amount, 'currency': currency, 'ack_ref': ack_ref, 'notified_at': datetime.datetime.now(datetime.timezone.utc).isoformat()}
    with open(NOTICE_LOG, 'a', encoding='utf-8') as f:
        f.write(json.dumps(entry) + '\n')


@function_tool
def notify_reinsurer_of_large_loss(claim_number: str, treaty_id: str, gross_loss_amount: float, date_of_loss: str, cause_of_loss: str, currency: str='USD') -> dict:
    if gross_loss_amount <= 0:
        return {'sent': False, 'error': 'gross_loss_amount must be positive'}
    cur = currency.upper().strip()
    if len(cur) != 3:
        return {'sent': False, 'error': f'Invalid currency code: {currency}'}
    body = {'cedent_claim_ref': claim_number, 'treaty_id': treaty_id, 'loss': {'gross_amount': round(gross_loss_amount, 2), 'currency': cur, 'date_of_loss': date_of_loss, 'cause': cause_of_loss[:500]}, 'notice_type': 'large_loss_advice'}
    hdrs = {'Authorization': f'Bearer {RI_KEY}', 'Content-Type': 'application/json', 'Idempotency-Key': str(uuid.uuid5(uuid.NAMESPACE_URL, f'{treaty_id}:{claim_number}'))}
    try:
        r = requests.post(f'{RI_API}/loss-notices', json=body, headers=hdrs, timeout=30)
    except requests.RequestException as e:
        return {'sent': False, 'error': f'Request failed: {e}'}
    if r.status_code >= 400:
        return {'sent': False, 'status': r.status_code, 'error': r.text[:1000]}
    d = r.json()
    result = {'sent': True, 'status': r.status_code, 'ack_ref': d.get('acknowledgement_id'), 'received_at': d.get('received_at')}
    _record_notice_sent(claim_number, treaty_id, round(gross_loss_amount, 2), cur, result['ack_ref'])
    return result
